<?php
namespace App\Http\Controllers;
use App\Models\{Course,CourseCategory,MembershipLevel,Enrollment};use Illuminate\Http\Request;use Illuminate\Support\Str;
class CourseController extends Controller {public function index(){ $courses=Course::with(['instructor','category'])->where('status','published')->latest()->paginate(12);return view('courses.index',compact('courses'));} public function manage(){abort_unless(in_array(auth()->user()->role,['admin','instructor']),403);$courses=Course::with('category')->when(auth()->user()->role==='instructor',fn($q)=>$q->where('instructor_id',auth()->id()))->latest()->paginate(15);return view('courses.manage',compact('courses'));} public function create(){abort_unless(in_array(auth()->user()->role,['admin','instructor']),403);return view('courses.form',['course'=>new Course,'categories'=>CourseCategory::all(),'levels'=>MembershipLevel::all()]);} public function store(Request $r){abort_unless(in_array(auth()->user()->role,['admin','instructor']),403);$d=$r->validate(['title'=>'required|string|max:180','description'=>'nullable|string','course_category_id'=>'nullable|exists:course_categories,id','required_membership_level_id'=>'nullable|exists:membership_levels,id','status'=>'required|in:draft,published,archived']);$d['slug']=Str::slug($d['title']).'-'.Str::lower(Str::random(5));$d['instructor_id']=auth()->id();$course=Course::create($d);return redirect()->route('courses.manage')->with('success','Course created.');} public function show(Course $course){abort_unless($course->status==='published'||in_array(auth()->user()->role,['admin','instructor']),404);$course->load(['instructor','category','lessons.materials']);$enrolled=Enrollment::where('student_id',auth()->id())->where('course_id',$course->id)->exists();return view('courses.show',compact('course','enrolled'));} public function edit(Course $course){abort_unless(auth()->user()->role==='admin'||$course->instructor_id===auth()->id(),403);return view('courses.form',['course'=>$course,'categories'=>CourseCategory::all(),'levels'=>MembershipLevel::all()]);} public function update(Request $r,Course $course){abort_unless(auth()->user()->role==='admin'||$course->instructor_id===auth()->id(),403);$d=$r->validate(['title'=>'required|string|max:180','description'=>'nullable|string','course_category_id'=>'nullable|exists:course_categories,id','required_membership_level_id'=>'nullable|exists:membership_levels,id','status'=>'required|in:draft,published,archived']);$course->update($d);return back()->with('success','Course updated.');} public function destroy(Course $course){abort_unless(auth()->user()->role==='admin'||$course->instructor_id===auth()->id(),403);$course->delete();return back()->with('success','Course deleted.');} public function enroll(Course $course){abort_unless(auth()->user()->role==='student',403);abort_unless($course->status==='published',404);$member=auth()->user()->member;if($course->required_membership_level_id){abort_unless($member&&$member->membership_level_id===$course->required_membership_level_id&&$member->status==='Active',403,'Your membership does not grant access to this course.');}Enrollment::firstOrCreate(['student_id'=>auth()->id(),'course_id'=>$course->id],['status'=>'active','enrolled_at'=>now()]);return redirect()->route('courses.show',$course)->with('success','You are enrolled in this course.');}}
